SELECT *, SUM(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, RANK() OVER (PARTITION BY city ORDER BY sqft NULLS LAST) AS sqft_rank, NTILE(3) OVER (PARTITION BY city, region ORDER BY sqft, id) AS sqft_bucket, SUM(sqft) OVER (PARTITION BY region) AS region_sum_sqft, LAG(sqft, 1, 0) OVER (PARTITION BY city ORDER BY sqft, id) AS prev_sqft FROM stores;
